import { mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const outputDirectory = fileURLToPath(
  new URL('../examples/vite-react/public/generated/', import.meta.url),
);

// One second, 320×180, silent H.264 fixture generated specifically for the
// development workbench. Keeping the encoded source here makes setup
// deterministic and avoids a network or ffmpeg dependency at runtime.
const videoBase64 =
  '';

function createWavFixture() {
  const sampleRate = 8_000;
  const sampleCount = sampleRate / 2;
  const bytes = Buffer.alloc(44 + sampleCount * 2);
  bytes.write('RIFF', 0);
  bytes.writeUInt32LE(bytes.length - 8, 4);
  bytes.write('WAVEfmt ', 8);
  bytes.writeUInt32LE(16, 16);
  bytes.writeUInt16LE(1, 20);
  bytes.writeUInt16LE(1, 22);
  bytes.writeUInt32LE(sampleRate, 24);
  bytes.writeUInt32LE(sampleRate * 2, 28);
  bytes.writeUInt16LE(2, 32);
  bytes.writeUInt16LE(16, 34);
  bytes.write('data', 36);
  bytes.writeUInt32LE(sampleCount * 2, 40);
  for (let index = 0; index < sampleCount; index += 1) {
    const sample = Math.sin((2 * Math.PI * 440 * index) / sampleRate) * 900;
    bytes.writeInt16LE(Math.round(sample), 44 + index * 2);
  }
  return bytes;
}

await mkdir(outputDirectory, { recursive: true });
await Promise.all([
  writeFile(
    new URL(
      '../examples/vite-react/public/generated/study-video.mp4',
      import.meta.url,
    ),
    Buffer.from(videoBase64, 'base64'),
  ),
  writeFile(
    new URL(
      '../examples/vite-react/public/generated/study-audio.wav',
      import.meta.url,
    ),
    createWavFixture(),
  ),
]);
console.log('Generated local development media fixtures.');
